plural <- function(n) {
  mod10 <- n %% 10
  mod100 <- n %% 100
  if (mod10 == 1) return("one")
  if (mod10 == 2) return("two")
  if (mod100 == 0 || mod100 == 20 || mod100 == 40 || mod100 == 60 || mod100 == 80) return("few")
  "other"
}

